using poke.battle.Models;
using poke.battle.Models.Impl;
using poke.battle.services;
using poke_battle_api.dtos;

namespace poke_battle_api.mappers.impl
{
    public class MoveMapper(IMapper<TypeDto, TypeModel> typesMapper, ITypeService typeService) : IMapper<MoveDto, MoveModel>
    {

        public MoveModel convertToBack(MoveDto model)
        {
            throw new NotImplementedException();
        }

 

        public MoveDto convertToFront(MoveModel model)
        {
            return new()
            {
                Id = model.Id,
                InternalName = model.Name,
                Name = model.DisplayName,
                Power = model.Power,
                Accuracy = model.Accuracy,
                Priority = model.Priority,
                Description = model.Description,
                Type = typesMapper.convertToFront(typeService.GetByName(model.Type)),
                Category = model.MoveType.ToString(),
                IconCategory = GetIconFromCategory(model.MoveType)

            };
        }

        private static string GetIconFromCategory(MoveType moveType)
        {
            if (MoveType.Physical == moveType)
                return "data:image/png;base64,";
            if (MoveType.Special == moveType)
                return "data:image/png;base64,";
            if (MoveType.Status == moveType)
                return "data:image/png;base64,";
            return string.Empty;
        }

        public IEnumerable<MoveModel> convertToBack(IEnumerable<MoveDto> list) => list.Select(convertToBack);
        public IEnumerable<MoveDto> convertToFront(IEnumerable<MoveModel> list) => list.Select(convertToFront);
    }
}
